/** Default maximum number of major ticks generated by `computeNiceTicks`. */
const _DEFAULT_MAX_TICKS = 5;

/** Floating-point comparison tolerance for tick boundary checks. */
const _FLOAT_TOLERANCE = 1e-10;

/** Threshold below which a tick value is snapped to exact zero. */
const _ZERO_SNAP_THRESHOLD = 1e-12;

/** Decimal places used to round floating-point noise in generated tick values. */
const _TICK_ROUNDING_DECIMALS = 8;

/** Safety cap on major tick loop iterations. */
const _MAX_MAJOR_TICKS_LOOP = 100;

/** Safety cap on minor tick loop iterations. */
const _MAX_ALL_TICKS_LOOP = 200;

/** Maximum number of minor ticks before falling back to major ticks only. */
const _MAX_DISPLAY_MINOR_TICKS = 40;

/** Minimum positive concentration floor for logarithmic transformations. */
const _MIN_LOG_CONCENTRATION = 1e-12;

/** Minimum allowed base-10 exponent during logarithmic X-axis panning. */
const _LOG_PAN_MIN_EXPONENT = -12;

/** Maximum allowed base-10 exponent during logarithmic X-axis panning. */
const _LOG_PAN_MAX_EXPONENT = 12;

/** Minimum drag box dimension (in pixels) required to trigger a 2D rectangular zoom. */
const _MIN_2D_DRAG_ZOOM_PX = 8;

/** Minimum drag box dimension (in pixels) along a single axis to trigger a 1D zoom. */
const _MIN_1D_DRAG_ZOOM_PX = 15;

/** Minimum visible decades required to render full logarithmic decade + minor ticks. */
const _FULL_LOG_TICKS_MIN_DECADES = 2;

/** Minimum visible decades required to render sparse (1, 2, 5) logarithmic ticks. */
const _SPARSE_LOG_TICKS_MIN_DECADES = 0.8;

/** Significant digits used to deduplicate zoomed X-axis ticks. */
const _ZOOMED_TICK_PRECISION = 8;

/** Minimum separation in log10 decades between LOD badges on the same vertical tier. */
const _MIN_LOD_BADGE_LOG_SEPARATION = 1.0;

/** Divisor applied to minimum positive concentration to position the synthetic zero tick. */
const _ZERO_X_DIVISOR = 10;

/** Multiplier applied to maximum standard concentration to provide right-hand axis headroom. */
const _MAX_X_AXIS_MULTIPLIER = 1.5;

/** Half-width of the X-axis zero-break gap in log10 decades (total gap = 0.26 decades). */
const _AXIS_BREAK_HALF_WIDTH_DECADES = 0.13;

/** Fractional bottom padding applied to the global Y-axis signal range. */
const _Y_MIN_PADDING_FRACTION = 0.05;

/** Fractional top padding applied to the global Y-axis signal range. */
const _Y_MAX_PADDING_FRACTION = 0.08;

/** Minimum allowed rough span when computing global Y-axis ticks. */
const _MIN_Y_ROUGH_SPAN = 1e-9;

/** Significant digits used when rounding global Y-axis ticks. */
const _Y_TICK_PRECISION = 10;

/**
 * Bounding box of the active Cartesian plot area within the SVG surface.
 */
export interface PlotArea {
  x: number;
  y: number;
  width: number;
  height: number;
}

/**
 * SVG pixel coordinates of a rectangular click-and-drag zoom gesture.
 */
export interface DragZoomBox {
  svgStartPx: number;
  svgCurrentPx: number;
  svgStartPy: number;
  svgCurrentPy: number;
}

/**
 * Computes human-readable major and minor linear axis ticks across `[min, max]`.
 *
 * @param min - Lower bound of the axis range.
 * @param max - Upper bound of the axis range.
 * @param maxTicks - Target number of major tick intervals (defaults to 5).
 * @returns Object containing `majorTicks` and `allTicks` arrays.
 */
export function computeNiceTicks(
  min: number,
  max: number,
  maxTicks: number = _DEFAULT_MAX_TICKS
): { majorTicks: number[]; allTicks: number[] } {
  const span = max - min;
  if (!Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(span) || span <= 0 || maxTicks <= 0) {
    return { majorTicks: [min], allTicks: [min] };
  }
  const roughStep = span / maxTicks;
  const magnitude = Math.pow(10, Math.floor(Math.log10(roughStep)));
  const normalizedStep = roughStep / magnitude;

  let multiplier = 1;
  if (normalizedStep >= 1.5 && normalizedStep < 3.5) multiplier = 2;
  else if (normalizedStep >= 3.5 && normalizedStep < 7.5) multiplier = 5;
  else if (normalizedStep >= 7.5) multiplier = 10;

  const niceStep = multiplier * magnitude;
  const niceStart = Math.ceil(min / niceStep) * niceStep;

  const majorTicks: number[] = [];
  let t = niceStart;
  let count = 0;
  while (t <= max + _FLOAT_TOLERANCE && count < _MAX_MAJOR_TICKS_LOOP) {
    const val = Math.abs(t) < _ZERO_SNAP_THRESHOLD ? 0 : Number(t.toFixed(_TICK_ROUNDING_DECIMALS));
    majorTicks.push(val);
    t += niceStep;
    count++;
  }

  const subDiv = multiplier === 2 ? 2 : 5;
  const subStep = niceStep / subDiv;
  const minorStart = Math.ceil(min / subStep) * subStep;
  const allTicks: number[] = [];
  t = minorStart;
  count = 0;
  while (t <= max + _FLOAT_TOLERANCE && count < _MAX_ALL_TICKS_LOOP) {
    const val = Math.abs(t) < _ZERO_SNAP_THRESHOLD ? 0 : Number(t.toFixed(_TICK_ROUNDING_DECIMALS));
    allTicks.push(val);
    t += subStep;
    count++;
  }

  return {
    majorTicks,
    allTicks: allTicks.length <= _MAX_DISPLAY_MINOR_TICKS ? allTicks : majorTicks,
  };
}

/**
 * Converts an SVG horizontal pixel coordinate to a logarithmic X-axis data concentration.
 *
 * @param px - Horizontal SVG pixel coordinate.
 * @param plotArea - Bounding box of the plot area in SVG pixel space.
 * @param xDomain - Active logarithmic `[min, max]` X-axis domain.
 * @returns Data concentration corresponding to `px`, clamped to `xDomain`.
 */
export function pixelToDataX(px: number, plotArea: PlotArea, xDomain: [number, number]): number {
  if (!Number.isFinite(xDomain[0]) || xDomain[0] <= 0) {
    return _MIN_LOG_CONCENTRATION;
  }
  if (!Number.isFinite(plotArea.width) || plotArea.width <= 0 || !Number.isFinite(xDomain[1]) || xDomain[1] <= 0) {
    return xDomain[0];
  }
  const fraction = (px - plotArea.x) / plotArea.width;
  const clampedFraction = Math.max(0, Math.min(1, fraction));
  const logMin = Math.log10(xDomain[0]);
  const logMax = Math.log10(xDomain[1]);
  const logVal = logMin + clampedFraction * (logMax - logMin);
  return Math.pow(10, logVal);
}

/**
 * Converts an SVG vertical pixel coordinate to a linear Y-axis signal value.
 *
 * @param py - Vertical SVG pixel coordinate (origin at top).
 * @param plotArea - Bounding box of the plot area in SVG pixel space.
 * @param yDomain - Active linear `[min, max]` Y-axis domain.
 * @returns Signal value corresponding to `py`, clamped to `yDomain`.
 */
export function pixelToDataY(py: number, plotArea: PlotArea, yDomain: [number, number]): number {
  if (!Number.isFinite(plotArea.height) || plotArea.height <= 0) {
    return yDomain[0];
  }
  const fraction = (plotArea.y + plotArea.height - py) / plotArea.height;
  const clampedFraction = Math.max(0, Math.min(1, fraction));
  return yDomain[0] + clampedFraction * (yDomain[1] - yDomain[0]);
}

/**
 * Evaluates a cubic ease-out curve $1 - (1 - t)^3$ for smooth zoom animations.
 *
 * @param progress - Normalized animation progress in $[0, 1]$.
 * @returns Eased progress value in $[0, 1]$.
 */
export function easeOutCubic(progress: number): number {
  if (!Number.isFinite(progress)) return 0;
  const clamped = Math.max(0, Math.min(1, progress));
  return 1 - Math.pow(1 - clamped, 3);
}

/**
 * Interpolates between two 2D chart domains, interpolating X logarithmically and Y linearly.
 *
 * @param fromDomain - Starting `{ x, y }` chart domain.
 * @param toDomain - Target `{ x, y }` chart domain.
 * @param progress - Normalized interpolation progress in $[0, 1]$.
 * @returns Interpolated `{ x, y }` chart domain at `progress`.
 */
export function interpolateDomain(
  fromDomain: { x: [number, number]; y: [number, number] },
  toDomain: { x: [number, number]; y: [number, number] },
  progress: number
): { x: [number, number]; y: [number, number] } {
  const p = Number.isFinite(progress) ? Math.max(0, Math.min(1, progress)) : 0;

  const fromLogMinX = Math.log10(Math.max(fromDomain.x[0], _MIN_LOG_CONCENTRATION));
  const fromLogMaxX = Math.log10(Math.max(fromDomain.x[1], _MIN_LOG_CONCENTRATION));
  const toLogMinX = Math.log10(Math.max(toDomain.x[0], _MIN_LOG_CONCENTRATION));
  const toLogMaxX = Math.log10(Math.max(toDomain.x[1], _MIN_LOG_CONCENTRATION));

  const currLogMinX = fromLogMinX + (toLogMinX - fromLogMinX) * p;
  const currLogMaxX = fromLogMaxX + (toLogMaxX - fromLogMaxX) * p;

  const currMinY = fromDomain.y[0] + (toDomain.y[0] - fromDomain.y[0]) * p;
  const currMaxY = fromDomain.y[1] + (toDomain.y[1] - fromDomain.y[1]) * p;

  return {
    x: [Math.pow(10, currLogMinX), Math.pow(10, currLogMaxX)],
    y: [currMinY, currMaxY],
  };
}

/**
 * Computes a panned `{ x, y }` domain from a mouse drag delta, shifting X in log10 space
 * (clamped to $[10^{-12}, 10^{12}]$) and Y in linear space.
 *
 * @param panStart - Initial X and Y domains when the right-click pan gesture started.
 * @param deltaX - Horizontal pointer displacement in pixels (positive = dragged right).
 * @param deltaY - Vertical pointer displacement in pixels (positive = dragged down).
 * @param plotArea - Bounding box of the plot area in SVG pixel space.
 * @returns Shifted `{ x, y }` domain.
 */
export function computePannedDomain(
  panStart: { xDomain: [number, number]; yDomain: [number, number] },
  deltaX: number,
  deltaY: number,
  plotArea: PlotArea
): { x: [number, number]; y: [number, number] } {
  const [startMinX, startMaxX] = panStart.xDomain;
  const [startMinY, startMaxY] = panStart.yDomain;

  if (
    !Number.isFinite(plotArea.width) ||
    plotArea.width <= 0 ||
    !Number.isFinite(plotArea.height) ||
    plotArea.height <= 0 ||
    startMinX <= 0 ||
    startMaxX <= startMinX
  ) {
    return { x: [startMinX, startMaxX], y: [startMinY, startMaxY] };
  }

  const logMin = Math.log10(startMinX);
  const logMax = Math.log10(startMaxX);
  const logSpan = logMax - logMin;
  const dLog = -(deltaX / plotArea.width) * logSpan;

  let newLogMin = logMin + dLog;
  let newLogMax = logMax + dLog;
  if (newLogMin < _LOG_PAN_MIN_EXPONENT) {
    newLogMin = _LOG_PAN_MIN_EXPONENT;
    newLogMax = newLogMin + logSpan;
  } else if (newLogMax > _LOG_PAN_MAX_EXPONENT) {
    newLogMax = _LOG_PAN_MAX_EXPONENT;
    newLogMin = newLogMax - logSpan;
  }
  const newXDomain: [number, number] = [Math.pow(10, newLogMin), Math.pow(10, newLogMax)];

  const ySpan = startMaxY - startMinY;
  const dY = (deltaY / plotArea.height) * ySpan;
  const newYDomain: [number, number] = [startMinY + dY, startMaxY + dY];

  return { x: newXDomain, y: newYDomain };
}

/**
 * Resolves a completed drag-selection box into a new zoomed `{ x, y }` domain, supporting
 * 2D rectangular zoom as well as 1D horizontal-only or vertical-only zoom gestures.
 *
 * @param dragBox - Start and end SVG pixel coordinates of the drag box.
 * @param plotArea - Bounding box of the plot area in SVG pixel space.
 * @param currentXDomain - Active X-axis domain prior to completing the drag.
 * @param currentYDomain - Active Y-axis domain prior to completing the drag.
 * @returns New `{ x, y }` zoom domain, or `null` if the drag gesture was too small.
 */
export function resolveDragZoomDomain(
  dragBox: DragZoomBox,
  plotArea: PlotArea,
  currentXDomain: [number, number],
  currentYDomain: [number, number]
): { x: [number, number]; y: [number, number] } | null {
  if (plotArea.width <= 0 || plotArea.height <= 0) {
    return null;
  }

  const px1 = Math.min(dragBox.svgStartPx, dragBox.svgCurrentPx);
  const px2 = Math.max(dragBox.svgStartPx, dragBox.svgCurrentPx);
  const py1 = Math.min(dragBox.svgStartPy, dragBox.svgCurrentPy);
  const py2 = Math.max(dragBox.svgStartPy, dragBox.svgCurrentPy);
  const width = px2 - px1;
  const height = py2 - py1;

  if (width >= _MIN_2D_DRAG_ZOOM_PX && height >= _MIN_2D_DRAG_ZOOM_PX) {
    const newXMin = pixelToDataX(px1, plotArea, currentXDomain);
    const newXMax = pixelToDataX(px2, plotArea, currentXDomain);
    const newYMax = pixelToDataY(py1, plotArea, currentYDomain);
    const newYMin = pixelToDataY(py2, plotArea, currentYDomain);

    if (newXMin > 0 && newXMax > newXMin && newYMax > newYMin) {
      return { x: [newXMin, newXMax], y: [newYMin, newYMax] };
    }
    return null;
  }

  if (width >= _MIN_1D_DRAG_ZOOM_PX && height < _MIN_2D_DRAG_ZOOM_PX) {
    const newXMin = pixelToDataX(px1, plotArea, currentXDomain);
    const newXMax = pixelToDataX(px2, plotArea, currentXDomain);
    if (newXMin > 0 && newXMax > newXMin) {
      return { x: [newXMin, newXMax], y: [currentYDomain[0], currentYDomain[1]] };
    }
    return null;
  }

  if (height >= _MIN_1D_DRAG_ZOOM_PX && width < _MIN_2D_DRAG_ZOOM_PX) {
    const newYMax = pixelToDataY(py1, plotArea, currentYDomain);
    const newYMin = pixelToDataY(py2, plotArea, currentYDomain);
    if (newYMax > newYMin) {
      return { x: [currentXDomain[0], currentXDomain[1]], y: [newYMin, newYMax] };
    }
    return null;
  }

  return null;
}

/**
 * Computes adaptive X-axis ticks when zoomed into a sub-range of the logarithmic concentration axis.
 *
 * @param activeXDomain - Current zoomed `[minX, maxX]` domain.
 * @param fallbackTicks - Base unzoomed ticks returned if `activeXDomain` is invalid.
 * @param breakStart - Lower bound of the zero-concentration axis break gap.
 * @param breakEnd - Upper bound of the zero-concentration axis break gap.
 * @returns Sorted array of unique X-axis tick values.
 */
export function computeZoomedXTicks(
  activeXDomain: [number, number],
  fallbackTicks: number[],
  breakStart: number,
  breakEnd: number
): number[] {
  const [minX, maxX] = activeXDomain;
  if (!Number.isFinite(minX) || !Number.isFinite(maxX) || minX <= 0 || maxX <= minX) {
    return fallbackTicks;
  }

  const logMin = Math.log10(minX);
  const logMax = Math.log10(maxX);
  const decades = logMax - logMin;
  const ticks: number[] = [];

  if (breakStart && breakEnd && minX <= breakStart && maxX >= breakEnd) {
    ticks.push(minX, breakStart, breakEnd);
  }

  if (decades >= _FULL_LOG_TICKS_MIN_DECADES) {
    const startExp = Math.floor(logMin);
    const endExp = Math.ceil(logMax);
    for (let i = startExp; i <= endExp; i++) {
      const pow10 = Math.pow(10, i);
      if (pow10 >= minX - _FLOAT_TOLERANCE && pow10 <= maxX + _FLOAT_TOLERANCE) {
        if (!breakStart || !breakEnd || pow10 < breakStart || pow10 > breakEnd) {
          ticks.push(pow10);
        }
      }
      if (i < endExp) {
        for (let j = 2; j <= 9; j++) {
          const minorVal = j * Math.pow(10, i);
          if (minorVal >= minX - _FLOAT_TOLERANCE && minorVal <= maxX + _FLOAT_TOLERANCE) {
            if (!breakStart || !breakEnd || minorVal < breakStart || minorVal > breakEnd) {
              ticks.push(minorVal);
            }
          }
        }
      }
    }
  } else if (decades >= _SPARSE_LOG_TICKS_MIN_DECADES) {
    const startExp = Math.floor(logMin);
    const endExp = Math.ceil(logMax);
    for (let i = startExp; i <= endExp; i++) {
      for (const m of [1, 2, 5]) {
        const val = m * Math.pow(10, i);
        if (val >= minX - _FLOAT_TOLERANCE && val <= maxX + _FLOAT_TOLERANCE) {
          if (!breakStart || !breakEnd || val < breakStart || val > breakEnd) {
            ticks.push(val);
          }
        }
      }
    }
  } else {
    const nice = computeNiceTicks(minX, maxX, _DEFAULT_MAX_TICKS);
    ticks.push(...nice.majorTicks);
  }

  return Array.from(new Set(ticks.map(t => Number(t.toPrecision(_ZOOMED_TICK_PRECISION))))).sort((a, b) => a - b);
}

/**
 * Computes the left and right bottom-axis line segments around the zero-concentration axis break.
 *
 * @param activeXDomain - Active `[minX, maxX]` domain.
 * @param minY - Bottom Y-axis coordinate where the horizontal axis line is drawn.
 * @param breakStart - Lower bound of the zero-concentration axis break gap.
 * @param breakEnd - Upper bound of the zero-concentration axis break gap.
 * @returns Object with `leftSegment` and `rightSegment` endpoint arrays.
 */
export function computeAxisBreakSegments(
  activeXDomain: [number, number],
  minY: number,
  breakStart: number,
  breakEnd: number
): { leftSegment: Array<{ x: number; y: number }>; rightSegment: Array<{ x: number; y: number }> } {
  const [minX, maxX] = activeXDomain;
  if (!Number.isFinite(minX) || !Number.isFinite(maxX) || maxX <= minX) {
    return { leftSegment: [], rightSegment: [] };
  }
  if (!breakStart || !breakEnd) {
    return {
      leftSegment: [
        { x: minX, y: minY },
        { x: maxX, y: minY },
      ],
      rightSegment: [],
    };
  }

  let leftSegment: Array<{ x: number; y: number }> = [];
  if (minX <= breakStart && maxX >= breakEnd) {
    leftSegment = [
      { x: minX, y: minY },
      { x: breakStart, y: minY },
    ];
  } else if (maxX <= breakStart) {
    leftSegment = [
      { x: minX, y: minY },
      { x: maxX, y: minY },
    ];
  }

  let rightSegment: Array<{ x: number; y: number }> = [];
  if (minX <= breakStart && maxX >= breakEnd) {
    rightSegment = [
      { x: breakEnd, y: minY },
      { x: maxX, y: minY },
    ];
  } else if (minX >= breakEnd) {
    rightSegment = [
      { x: minX, y: minY },
      { x: maxX, y: minY },
    ];
  }

  return { leftSegment, rightSegment };
}

/**
 * Assigns collision-free vertical tier indices (`0, 1, 2, ...`) to multi-curve LOD badges
 * so badges within 1.0 log10 decade of each other are staggered vertically.
 *
 * @param seriesEntries - List of series identifiers and their estimated LOD concentrations.
 * @returns Map from series ID to its assigned vertical tier index.
 */
export function computeLodBadgeTiers(
  seriesEntries: ReadonlyArray<{ id: string; lodConc: number }>
): Map<string, number> {
  if (seriesEntries.length <= 1) {
    return new Map<string, number>();
  }
  const valid = seriesEntries.filter(s => Number.isFinite(s.lodConc) && s.lodConc > 0);
  const sorted = [...valid].sort((a, b) => a.lodConc - b.lodConc);
  const tierLastLogX: number[] = [];
  const map = new Map<string, number>();

  for (const s of sorted) {
    const logX = Math.log10(Math.max(s.lodConc, _MIN_LOG_CONCENTRATION));
    let assignedTier = -1;

    for (let t = 0; t < tierLastLogX.length; t++) {
      if (logX - tierLastLogX[t] >= _MIN_LOD_BADGE_LOG_SEPARATION) {
        assignedTier = t;
        tierLastLogX[t] = logX;
        break;
      }
    }

    if (assignedTier === -1) {
      assignedTier = tierLastLogX.length;
      tierLastLogX.push(logX);
    }

    map.set(s.id, assignedTier);
  }

  return map;
}

/**
 * Computes the global logarithmic X-axis domain, synthetic zero position, axis-break bounds,
 * and major/minor tick list across all visible curve series.
 *
 * @param seriesEntries - Visible series entries containing standard concentrations, LOD, and lower CI bound.
 * @returns Object with `xTicks`, `xDomain`, `breakStart`, and `breakEnd`.
 */
export function computeGlobalLogXAxisLayout(
  seriesEntries: ReadonlyArray<{ actualX: number[]; lodConc: number; lodCILow: number }>
): { xTicks: number[]; xDomain: [number, number]; breakStart: number; breakEnd: number } {
  if (seriesEntries.length === 0) {
    return { xTicks: [], xDomain: [0, 0], breakStart: 0, breakEnd: 0 };
  }
  const allPositiveStandards = seriesEntries.flatMap(item =>
    item.actualX.filter(x => Number.isFinite(x) && x > 0)
  );
  if (allPositiveStandards.length === 0) {
    return { xTicks: [], xDomain: [0, 0], breakStart: 0, breakEnd: 0 };
  }

  const validLODs = seriesEntries
    .map(item => item.lodConc)
    .filter(lod => Number.isFinite(lod) && lod > 0);
  const validCILows = seriesEntries
    .map(item => item.lodCILow)
    .filter(low => Number.isFinite(low) && low > 0);

  const minPositiveCandidate = Math.min(...allPositiveStandards, ...validLODs, ...validCILows);
  const maxPositiveCandidate = Math.max(...allPositiveStandards, ...validLODs);

  const zeroX = minPositiveCandidate / _ZERO_X_DIVISOR;
  const maxAxisValue = maxPositiveCandidate * _MAX_X_AXIS_MULTIPLIER;
  const logZero = Math.log10(zeroX);
  const logMinPositive = Math.log10(minPositiveCandidate);
  const breakCenterLog = (logZero + logMinPositive) / 2;
  const breakStart = Math.pow(10, breakCenterLog - _AXIS_BREAK_HALF_WIDTH_DECADES);
  const breakEnd = Math.pow(10, breakCenterLog + _AXIS_BREAK_HALF_WIDTH_DECADES);
  const logMin = Math.floor(Math.log10(zeroX));
  const logMax = Math.ceil(Math.log10(maxAxisValue));
  const ticks = [zeroX, breakStart, breakEnd];

  for (let i = logMin; i <= logMax; i++) {
    const majorVal = Math.pow(10, i);
    if (majorVal <= maxAxisValue && majorVal >= minPositiveCandidate - _FLOAT_TOLERANCE) {
      if (majorVal < breakStart || majorVal > breakEnd) ticks.push(majorVal);
    }
    if (i < logMax) {
      for (let j = 2; j <= 9; j++) {
        const minorVal = j * Math.pow(10, i);
        if (minorVal <= maxAxisValue && minorVal >= minPositiveCandidate - _FLOAT_TOLERANCE) {
          if (minorVal < breakStart || minorVal > breakEnd) ticks.push(minorVal);
        }
      }
    }
  }

  return { xTicks: ticks, xDomain: [zeroX, maxAxisValue], breakStart, breakEnd };
}

/**
 * Computes the global linear Y-axis domain and major/minor tick arrays across all visible series.
 *
 * @param seriesEntries - Visible series entries containing measured signals, $L_C$, and $L_D$.
 * @returns Object containing `yDomain`, `yTicks` (all ticks), and `yMajorTicks`.
 */
export function computeGlobalLinearYAxisLayout(
  seriesEntries: ReadonlyArray<{ actualY: number[]; lc: number; ld: number }>
): { yDomain: [number, number]; yTicks: number[] | undefined; yMajorTicks: number[] } {
  if (seriesEntries.length === 0) {
    return { yDomain: [0, 1], yTicks: undefined, yMajorTicks: [] };
  }
  const allSignals = seriesEntries.flatMap(item => item.actualY.filter(v => Number.isFinite(v)));
  const allKeyValues = [...allSignals];
  seriesEntries.forEach(item => {
    if (Number.isFinite(item.lc)) allKeyValues.push(item.lc);
    if (Number.isFinite(item.ld)) allKeyValues.push(item.ld);
  });

  const minData = allKeyValues.length > 0 ? Math.min(...allKeyValues) : 0;
  const maxData = allKeyValues.length > 0 ? Math.max(...allKeyValues) : 1;

  const span = maxData > minData ? maxData - minData : Math.abs(maxData) || 1;
  const targetMin =
    minData < 0 ? minData - span * _Y_MIN_PADDING_FRACTION : Math.max(0, minData - span * _Y_MIN_PADDING_FRACTION);
  const targetMax = maxData + span * _Y_MAX_PADDING_FRACTION;
  const roughSpan = Math.max(_MIN_Y_ROUGH_SPAN, targetMax - targetMin);

  const rawStep = roughSpan / _DEFAULT_MAX_TICKS;
  const magnitude = Math.pow(10, Math.floor(Math.log10(rawStep)));
  const normalizedStep = rawStep / magnitude;

  let multiplier = 1;
  if (normalizedStep >= 1.5 && normalizedStep < 3.5) multiplier = 2;
  else if (normalizedStep >= 3.5 && normalizedStep < 7.5) multiplier = 5;
  else if (normalizedStep >= 7.5) multiplier = 10;

  const niceStep = multiplier * magnitude;
  const niceMin = Math.floor(targetMin / niceStep) * niceStep;
  const niceMax = Math.ceil(targetMax / niceStep) * niceStep;

  const numMajor = Math.max(1, Math.round((niceMax - niceMin) / niceStep));
  const majorTicks: number[] = [];
  for (let i = 0; i <= numMajor; i++) {
    majorTicks.push(Number((niceMin + i * niceStep).toPrecision(_Y_TICK_PRECISION)));
  }

  const subDiv = multiplier === 2 ? 2 : 5;
  const subStep = niceStep / subDiv;
  const numMinor = Math.round((niceMax - niceMin) / subStep);
  const allTicks: number[] = [];
  if (numMinor <= _MAX_DISPLAY_MINOR_TICKS) {
    for (let i = 0; i <= numMinor; i++) {
      allTicks.push(Number((niceMin + i * subStep).toPrecision(_Y_TICK_PRECISION)));
    }
  } else {
    allTicks.push(...majorTicks);
  }

  return { yDomain: [niceMin, niceMax], yTicks: allTicks, yMajorTicks: majorTicks };
}
